import{c as a,Q as l,j as s,m as i}from"./chunks/framework.DOi4mjdC.js";const n="/assets/zh-cn_image_0000002411422713.C7d2qM4n.png",e="/assets/zh-cn_image_0000002411018580.Bxle1Wgi.png",p="/assets/%E9%BB%98%E8%AE%A4%E4%B8%8D%E4%BD%BF%E8%83%BDTiling%E5%B8%B8%E9%87%8F%E5%8C%96%E7%9A%84Matmul%E8%AE%A1%E7%AE%97%E6%B5%81%E7%A8%8B%E7%A4%BA%E6%84%8F%E5%9B%BE.BgodpJu_.png",o="/assets/%E4%BD%BF%E8%83%BDTiling%E5%B8%B8%E9%87%8F%E5%8C%96%E7%9A%84Matmul%E8%AE%A1%E7%AE%97%E6%B5%81%E7%A8%8B%E7%A4%BA%E6%84%8F%E5%9B%BE.CKCDciM9.png",u="/assets/zh-cn_image_0000002377921500.BtXx9eyg.png",g="/assets/zh-cn_image_0000002411019880.9l3icxBF.png",q=JSON.parse('{"title":"Matmul高阶API使能Tiling全量常量化","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul高阶API使能Tiling全量常量化","slug":"matmul高阶api使能tiling全量常量化"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能Tiling全量常量化.md","filePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能Tiling全量常量化.md"}'),r={name:"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能Tiling全量常量化.md"};function c(m,t,d,_,M,h){return l(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="matmul高阶api使能tiling全量常量化" tabindex="-1">Matmul高阶API使能Tiling全量常量化 <a class="header-anchor" href="#matmul高阶api使能tiling全量常量化" aria-label="Permalink to &quot;Matmul高阶API使能Tiling全量常量化&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例呈现了在使用Matmul高阶API进行矩阵乘法计算时，使能Matmul Tiling全量常量化对算子性能的提升效果。Matmul API在初始化和迭代过程中有大量Scalar计算，Matmul初始化时的Scalar计算影响指令头开销，Matmul迭代间的Scalar计算可能阻塞MTE2流水。在调用Matmul API实现矩阵乘法时，使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Matmul%E6%A8%A1%E6%9D%BF%E5%8F%82%E6%95%B0.md" target="_blank" rel="noreferrer">MatmulApiStaticTiling</a>参数替代TCubeTiling变量参数，将Scalar计算提前到编译期进行，以减少运行时的Scalar计算开销，实现算子性能的提升。</p><ul><li><p>Matmul Tiling常量化的适用场景：</p><ul><li>Matmul初始化时的Scalar计算较多，影响指令头开销。</li><li>Matmul迭代之间的Scalar计算较多，阻塞MTE2流水。</li></ul></li><li><p>Matmul Tiling常量化需要在编译期确定部分Tiling参数，根据确定参数的不同，分为全量常量化和部分常量化两种场景，使用Matmul Tiling常量化需要满足两种场景中任一场景的条件：</p><ul><li><p>全量常量化：能够确定常量singleCore Shape（singleCoreM/singleCoreN/singleCoreK）和常量base Shape（basicM/basicN/basicK，也称baseM/baseN/baseK）。</p></li><li><p>部分常量化：能够确定常量base Shape（basicM/basicN/basicK，也称baseM/baseN/baseK）。</p></li></ul><p>其中，全量常量化场景比部分常量化场景可以减少更多的Scalar计算开销。</p></li></ul><p>本案例的算子规格如下：</p><p><strong>表 1</strong> 算子规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;输入&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Shape&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Data type&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Format&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;a&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;128, 64&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;b&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;64, 30720&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>当前案例使用的AI处理器共24个核，每个核中包含1个AIC核和2个AIV核。</p><p>Tiling参数如下：</p><ul><li><p>原始shape：M=128, N=30720, K=64。</p></li><li><p>单核shape：按24个AIC核进行切分，singleCoreM=128，singleCoreN=1280，singleCoreK=64。</p><p>对于B矩阵，沿着N轴进行切分，切分成24份的singleCoreN，单核上处理K * singleCoreN大小的数据。对于A矩阵，M轴不进行切分即singleCoreM=M，单核上处理singleCoreM * K大小的数据。总共24个核参与计算。</p></li><li><p>基本块shape：baseM=128，baseN=256，baseK=64。</p></li><li><p>L1相关Tiling参数：stepM=1，stepN=1，stepKa=4，stepKb=4，depthA1=8，depthB1=8。</p></li></ul><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>使用msProf工具获取<a href="./../../性能分析/获取性能数据.html#section17259539153513">算子仿真流水图</a>和<a href="./../../性能分析/获取性能数据.html#section17953123893415">上板Profiling</a>数据。相较于基础场景，Tiling常量化在编译期期间将部分或全部Tiling参数由变量转化为常数值，在算子执行时直接使用常量化的Tiling参数，可以减少Scalar性能开销，所以重点分析Scalar流水。</p><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><ul><li><p>优化前的流水图如下，默认不使能Tiling常量化，Tiling参数需要从Host侧拷贝到Kernel侧，导致Matmul初始化时的Scalar计算较多，第一个MTE2指令开始于3.536us左右，MTE2前的指令头开销在算子整个流水中占比较大，因此需要优化Scalar计算。</p><p><img src="'+n+'" alt=""></p></li><li><p>优化前的Profiling数据如下，从C列的aic_time数据来看，多个核中最大算子执行耗时为10.62us，从G列的aic_scalar_time数据来看，Scalar平均耗时6.32us。</p><p><img src="'+e+'" alt=""></p></li></ul><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><p>如下图所示，默认不使能Tiling常量化功能时，开发者在host侧创建Tiling对象，通过调用API自动获取Tiling参数。然后将Tiling参数从Host侧传递到Kernel侧，在Kernel侧初始化操作时传入。在算子执行时，使用Tiling变量参数完成矩阵乘操作。</p><p><strong>图 1</strong> 默认不使能Tiling常量化的Matmul计算流程示意图<br><img src="'+p+'" alt="" title="默认不使能Tiling常量化的Matmul计算流程示意图"></p><p>如下图所示，使能Tiling常量化功能时，开发者只需要在Kernel侧创建Matmul对象时，调用GetMatmulApiTiling接口在编译期获取常量化Tiling信息，即可完成Tiling常量化。在算子执行时，使用常量化的Tiling参数完成矩阵乘操作，减少Scalar计算开销。</p><p><strong>图 2</strong> 使能Tiling常量化的Matmul计算流程示意图<br><img src="'+o+`" alt="" title="使能Tiling常量化的Matmul计算流程示意图"></p><p>Matmul API使能Tiling全量常量化的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_constant_tiling" target="_blank" rel="noreferrer">Matmul Tiling常量化的算子样例</a>。使能Tiling全量常量化功能的步骤如下：</p><ol><li><p>调用获取MatmulConfig模板的接口GetMMConfig时，使用常数值设置MatmulShapeParams，得到带有常量化参数的自定义MatmulConfig模板CUSTOM_CFG。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>constexpr int32_t MAX_M = 10000; // custom matmul kernel support max value of M Dim shape</span></span>
<span class="line"><span>constexpr int32_t MAX_N = 10000; // custom matmul kernel support max value of N Dim shape</span></span>
<span class="line"><span>constexpr int32_t MAX_K = 10000; // custom matmul kernel support max value of K Dim shape</span></span>
<span class="line"><span>constexpr int32_t BASE_M = 128;  // BASE_M * BASE_K * sizeof(typeA) &lt;=L0A size</span></span>
<span class="line"><span>constexpr int32_t BASE_N = 256;  // BASE_N * BASE_K * sizeof(typeB) &lt;=L0B size</span></span>
<span class="line"><span>constexpr int32_t BASE_K = 64;   // BASE_M * BASE_N * sizeof(typeC) &lt;=L0C size</span></span>
<span class="line"><span>constexpr MatmulShapeParams shapeParams = { MAX_M,</span></span>
<span class="line"><span>                                            MAX_N,</span></span>
<span class="line"><span>                                            MAX_K,</span></span>
<span class="line"><span>                                            BASE_M,</span></span>
<span class="line"><span>                                            BASE_N,</span></span>
<span class="line"><span>                                            BASE_K };</span></span>
<span class="line"><span>constexpr MatmulConfig CUSTOM_CFG = GetMMConfig&lt;MatmulConfigMode::CONFIG_MDL&gt;(shapeParams);</span></span></code></pre></div></li><li><p>创建Matmul对象。首先调用GetMatmulApiTiling接口，将Tiling信息常量化，得到常量化模板参数CONSTANT_CFG，包括常量化的Matmul Tiling信息和MatmulConfig模板。创建Matmul对象时，使用常量化模板参数CONSTANT_CFG。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>using A_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, aType&gt;;</span></span>
<span class="line"><span>using B_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, bType&gt;;</span></span>
<span class="line"><span>using C_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, cType&gt;;</span></span>
<span class="line"><span>using BIAS_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, biasType&gt;;</span></span>
<span class="line"><span>constexpr static auto CONSTANT_CFG = AscendC::GetMatmulApiTiling&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE&gt;(CUSTOM_CFG);</span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CONSTANT_CFG&gt; matmulObj;</span></span></code></pre></div></li><li><p>初始化操作。全量常量化时，可以在REGIST_MATMUL_OBJ接口的入参传递Tiling参数的位置，使用空指针替代。部分常量化时，在Kernel侧使用REGIST_MATMUL_OBJ接口初始化Matmul对象时，仍需要使用Tiling。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 全量常量化场景，初始化操作示例</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), matmulObj, (TCubeTiling*)nullptr);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 部分常量化场景，初始化操作示例</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), matmulObj, &amp;tiling);</span></span></code></pre></div></li></ol><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><ul><li><p>优化后的流水图如下，通过使能Tiling全量常量化，无需将Tiling参数从Host侧拷贝到Kernel侧，在编译期完成Tiling常量化，减少了Matmul初始化时的Scalar计算。从0us起到第一个MTE2指令发起，这之间的时间为Matmul初始化时间，Matmul初始化时间从优化前的3.536us减少到2.185us，性能有所提升。</p><p><img src="`+u+'" alt=""></p></li><li><p>优化后的Profiling数据如下，从C列的aic_time数据来看，多个核中最大算子执行耗时为7.87us，相较于优化前的10.62us提升了25.9%。从G列的aic_scalar_time数据来看，Scalar平均耗时3.38us，相较于优化前的6.32us提升了46.5%。</p><p><img src="'+g+'" alt=""></p></li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>算子在调用Matmul API完成矩阵乘计算时，若Matmul初始化时的Scalar计算较多，影响了指令头开销，或Matmul迭代间的Scalar计算较多，阻塞了MTE2流水。在这两类场景下，满足上文提及的Tiling常量化使能条件（<a href="#li159920538152">全量常量化</a>或<a href="#li98655581816">部分常量化</a>），可以考虑使能Tiling常量化，减少Scalar计算开销，提升算子性能。</p>',25)])])}const A=a(r,[["render",c]]);export{q as __pageData,A as default};
